static void cmd_sha256() {
    if (argc < 2) {
        print_color("\n  Usage: sha256 <text>\n\n", MAKE_COLOR(COLOR_LIGHT_RED, COLOR_BLACK));
        return;
    }
    // Hash argv[1] (single token)
    const char* s = argv[1];
    int len = 0; while (s[len]) len++;
    uint8_t digest[32];
    char hex[65];
    sha256((const uint8_t*)s, len, digest);
    sha256_hex(digest, hex);
    print("\n  sha256(\"");
    print(s);
    print("\") =\n  ");
    print_color(hex, MAKE_COLOR(COLOR_LIGHT_GREEN, COLOR_BLACK));
    print("\n\n");
}

