    print_color("\n  Playing scale (C major)...\n\n", YELLOW_ON_BLACK);

    int notes[]    = { NOTE_C4, NOTE_D4, NOTE_E4, NOTE_F4,
                       NOTE_G4, NOTE_A4, NOTE_B4, NOTE_C5 };
    const char* nm[] = { "C", "D", "E", "F", "G", "A", "B", "C" };

    for (int i = 0; i < 8; i++) {
        print("  ");
        print(nm[i]);
        beep((uint32_t)notes[i], 200);
        sleep_ms(40);
    }
    print("\n\n");
